BIR_st.name='BIR';
BIR_st.lat=58.3886;
BIR_st.lon=8.251944;
BIR_st.alt=219;
BIR_st.env='con';
BIR_st.footp='F';
%%
 
BIR_rd=read_ebas_merged_STN('C:\github_trend\raw_data\merged_Birkenes.nc',BIR_st.name); %[output:2cf9f2f7]

names_rd=fieldnames(BIR_rd);
%BIR_rd=read_betsy('BIR_2009_2017', BIR_st.name);
%%
% read AE send separately
BIR_rdAE= read_all_data_INO_Ttable('AE33','lev2','C:/github_trend/raw_data/BIR/AE33_BIR_2017-2022/');%read all nasa ames read_betsy_2026('INO_tsi_psap_clap_eco',INO_st.name); %[output:86d0e03a]
%%
%[output:5963399a]
%%
BIR_rdAE.Properties.VariableNames{3}='Babs1_AE33';
BIR_rdAE.Properties.VariableNames{4}='Babs2_AE33';
BIR_rdAE.Properties.VariableNames{5}='Babs3_AE33';
BIR_rdAE.Properties.VariableNames{6}='Babs4_AE33';
BIR_rdAE.Properties.VariableNames{7}='Babs5_AE33';
BIR_rdAE.Properties.VariableNames{8}='Babs6_AE33';
BIR_rdAE.Properties.VariableNames{9}='Babs7_AE33';
BIR_rdAE=retime(BIR_rdAE,'daily',@nanmedian);
BIR_rd=outerjoin(BIR_rd,BIR_rdAE);
% still old 1w U PSAP higher until June 2012. Data Jan-Jun 2012 could be
% taken
%--> either use 470 2013-2025 (Ba20_A) or add Jan-Jun2012 from Ba5220_A
%%

% read new AE 2022 data send 12.101.2026
BIR_rdAE22= read_all_data_INO_Ttable('AE33','lev2','C:/github_trend/raw_data/BIR/');%read all nasa ames read_betsy_2026('INO_tsi_psap_clap_eco',INO_st.name);
BIR_rdAE22_d=retime(BIR_rdAE22,'daily',@nanmedian);
%%

BIR_rdAE22_d.starttime=[];
BIR_rdAE22_d.endtime=[];
BIR_rdAE22_d.numflag=[];


P22=timerange('2022-01-01','2023-01-01');
names_rd=fieldnames(BIR_rd);
names_AE=names_rd(startsWith(names_rd,'Babs') & endsWith(names_rd,'_AE33'));
names_AE22=fieldnames(BIR_rdAE22_d);
for i=1:length(names_AE)
    BIR_rd.(names_AE{i})(P22)=BIR_rdAE22_d.(names_AE22{i})(P22);
end
%%
datevec(BIR_rd.Time(1)) % begin in 2008 May NO in 2010 for all data. %[output:3f56ab27]
datevec(BIR_rd.Time(end)) % end in 2025 %[output:6774de40]
prctile(BIR_rd.U370_S,[5 50 95]) % < 40%, ok. %[output:572c4cfd]
plotFigControl(BIR_rd,BIR_st.name); %[output:3a0e159d] %[output:0cdbcdb8] %[output:76fc0995] %[output:723760dc] %[output:4f01e7af] %[output:7424f581] %[output:64baf564]


%%
BIR_rd.Properties.VariableNames{15}='BsG0_S';
BIR_rd.Properties.VariableNames{16}='BsR0_S';
BIR_rd.Properties.VariableNames{12}='BbsG0_S';
BIR_rd.Properties.VariableNames{13}='BbsR0_S';
BIR_rd.Properties.VariableNames{22}='BsG0_S_dry';
BIR_rd.Properties.VariableNames{23}='BsR0_S_dry';
BIR_rd.Properties.VariableNames{19}='BbsG0_S_dry';
BIR_rd.Properties.VariableNames{20}='BbsR0_S_dry';
%%
% BP detection for scat coef and backscat

names_sc={'BsB0_S', 'BsG0_S', 'BsR0_S'};
break_BIR_scat_BP=change_point_analysis_Def(BIR_rd,names_sc,0.05,'BIR','scattering'); %[output:9f366060] %[output:267f9610] %[output:6fcc3286] %[output:963ad739]
T_BIR_scat_BP=make_table_breakpoints_def(break_BIR_scat_BP);

names_bsc={'BbsB0_S', 'BbsG0_S', 'BbsR0_S'};
break_BIR_bscat_BP=change_point_analysis_Def(BIR_rd,names_bsc,0.05,'BIR','Backscattering'); %[output:5424598b] %[output:8febe217] %[output:010f4ca5] %[output:13f7e5f2]
T_BIR_bscat_BP=make_table_breakpoints_def(break_BIR_bscat_BP);
%%
% try to homogenised PSAP AE33 (either 470 or 520) in 2018-2022
Pt=timerange('2018-01-01','2022-01-01');
ratio_med_h=nanmedian(BIR_rd.Babs3_AE33(Pt)./BIR_rd.Ba5220_A(Pt)) % 0.5667 %[output:3a252c72]
ratio_STN_h=nanstd(BIR_rd.Babs3_AE33(Pt)./BIR_rd.Ba5220_A(Pt)) %  0.2898 %[output:284831c8]
ratio_mean_h=nanmean(BIR_rd.Babs3_AE33(Pt)./BIR_rd.Ba5220_A(Pt)) % 0.5765 %[output:15d40027]
ratio_mean=nanmean(BIR_rd.Babs3_AE33(Pt))/nanmean(BIR_rd.Ba5220_A(Pt)) % 0.5900 %[output:056c7144]
ratio_median=nanmedian(BIR_rd.Babs3_AE33(Pt))/nanmedian(BIR_rd.Ba5220_A(Pt)) % 0.5859 %[output:20cf6f89]
figure; %[output:715d5590]
plot(BIR_rd.Ba5220_A(Pt),BIR_rd.Babs3_AE33(Pt),'.'); %[output:715d5590]

% fit between both data: slope 0.5345x+0.04265
fit_test=robustfit(BIR_rd.Ba5220_A(Pt),BIR_rd.Babs3_AE33(Pt)) % y coor=0.0190, slope=0.5420 %[output:8f1fa6e7]
cte_psap_AE33=0.54;
%%
P1=timerange('2012-01-01','2023-01-01');
P2=timerange('2018-01-01','2023-01-01');
P3=timerange('2023-01-01','2026-01-01');

BIR_rd.BaG_Ah=NaN(size(BIR_rd.Ba30_A));
BIR_rd.BaG_Ah(P1)=BIR_rd.Ba5220_A(P1).*cte_psap_AE33;
BIR_rd.BaG_Ah(P3)=BIR_rd.Ba30_A(P3);
BIR_rd.BaG_Ah(P2)=BIR_rd.Babs3_AE33(P2);

BIR_rd.BaB_Ah=NaN(size(BIR_rd.Ba20_A));
BIR_rd.BaB_Ah(P1)=BIR_rd.Ba20_A(P1).*cte_psap_AE33;
BIR_rd.BaB_Ah(P3)=BIR_rd.Ba20_A(P3);
BIR_rd.BaB_Ah(P2)=BIR_rd.Babs2_AE33(P2);

BIR_rd.BaR_Ah=NaN(size(BIR_rd.Ba6600_A));
BIR_rd.BaR_Ah(P1)=BIR_rd.Ba6600_A(P1).*cte_psap_AE33;
BIR_rd.BaR_Ah(P3)=BIR_rd.Ba50_A(P3);
BIR_rd.BaR_Ah(P2)=BIR_rd.Babs5_AE33(P2);
%%
% BP detection for abs
names_abs={'Ba5220_A','Ba20_A','BaB_Ah','BaG_Ah','BaR_Ah'};
break_BIR_abs_BP=change_point_analysis_Def(BIR_rd,names_abs,0.05,'BIR','Absorption'); %[output:0df46548] %[output:3ec59d81] %[output:79276f37] %[output:1de6f2fa] %[output:19222f67] %[output:968223a4]
T_BIR_abs_BP=make_table_breakpoints_def(break_BIR_abs_BP); %[output:749b37f3]

%%
lambdaSC=[450;550;700];
lambdaAE=[470;520;660];
names_neph={'BsB0_S', 'BsG0_S', 'BsR0_S','BbsB0_S','BbsG0_S','BbsR0_S'};
BIR_expS=compute_exp_D(BIR_rd,names_neph,lambdaSC);
names_abs={'BaB_Ah', 'BaG_Ah', 'BaR_Ah'};
BIR_expA=compute_exp_D(BIR_rd,names_abs,lambdaAE);
BIR_cal=outerjoin(BIR_expS,BIR_expA);

BIR_SSA=compute_SSA_D(BIR_rd, names_sc, names_abs);
BIR_cal.SSAG=BIR_rd.BsG0_S./(BIR_rd.BsG0_S+BIR_rd.BaG_Ah);
plotFigControl_cal(BIR_cal, BIR_st.name); %[output:095d8f80] %[output:35a6b70d] %[output:2aa73a3e]
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg'};
break_BIR_exps_BP=change_point_analysis_Def(BIR_cal,names_exps,0.05,'BIR','scattering exp'); %[output:93c8a306] %[output:829afffe]
T_BIR_exps_BP=make_table_breakpoints_def(break_BIR_exps_BP);
%%

names_BbF={'BbsFg'};
break_BIR_BbF_BP=change_point_analysis_Def(BIR_cal,names_BbF,0.05,'BIR','backscat fraction'); %[output:54cdc61f] %[output:9acc6202]
T_BIR_BbF_BP=make_table_breakpoints_def(break_BIR_BbF_BP); %[output:083ce835] %[output:62da104b] %[output:29825947] %[output:06109e2b]

names_SSA={'SSAG'};
break_BIR_SSA_BP=change_point_analysis_Def(BIR_cal,names_SSA,0.05,'BIR','SSA'); %[output:31e7613d] %[output:3e5ebe8d]
T_BIR_SSA_BP=make_table_breakpoints_def(break_BIR_SSA_BP);
%%
%Questions:
%problems:
%SC: becomes lower since October 2017 (perhaps abs also ??)
% BSP becomes more noisy during winter sin end 2016 (aging?)
%bsp: ratio between 2 w are higher til mid 2010, less visible in sc ratio (just for B/G)
% exp bg min higher in the first mid 2010
%%
%2018 files already downloaded
%%
BIR_tr=outerjoin(BIR_rd,BIR_cal);
BIR_tr.y=year(BIR_tr.Time);
% begin at the beginning of a year: 2010 (2017: 8y)
P=timerange('2010-01-01','2026-01-01');
BIR_tr=BIR_tr(P,:);

%no data in Ba2_A11 and Ba3_A11
names=fieldnames(BIR_tr);
c= startsWith(names,["start";"end";"U";"numflag";"Babs"]) |  endsWith(names,["_A";"dry";"B0_S";"R0_S";"_br";"_gr";"Fb";"Fr";"B_Ah";"R_Ah"]);
N=names(c);
for i=1:length(N)
    BIR_tr.(N{i})=[];
end

%REMOVE bBSfFg IN 2025 AND EXPA for final results after feedback
P25=timerange('2025-01-01','2026-01-01');
BIR_tr.BbsFg(P25)=NaN;
BIR_tr.expA_bg=[];
%%
[BIR_result_MK,BIR_result_LMSlog,BIR_result_LMSlin]=all_trend_STN(BIR_tr,BIR_st); %[output:89ec7b6a] %[output:02c2a260] %[output:7b597416] %[output:5e0730b4] %[output:0a77ca23] %[output:98302af8] %[output:59bf37bc] %[output:5fa51a3a] %[output:68158f87] %[output:54433e9d] %[output:45d58546] %[output:8d6bc91a] %[output:8c80b827] %[output:0698242f] %[output:00f9676d] %[output:8075d472] %[output:39b00a22] %[output:0c884394] %[output:87456d28] %[output:5a44ac5a] %[output:15beb499] %[output:69edb596] %[output:8c72c057] %[output:43ee1e7e] %[output:7b9f1f1a] %[output:7879666a] %[output:1d40e8e3] %[output:1756aa7c] %[output:5cccf4b7] %[output:25399f08] %[output:7057d39c] %[output:8f627dc2] %[output:420dc4eb] %[output:10e046aa] %[output:2c9a5af1] %[output:7c4bdc6e] %[output:12551d39] %[output:8fd24dc5] %[output:82746034] %[output:273f131c] %[output:98872cad] %[output:59eaa191] %[output:5d9ead2b] %[output:8647785c] %[output:5721a520] %[output:43e00258] %[output:1022310a] %[output:31086a77] %[output:6295b162] %[output:3f30d5e7] %[output:4554e60f] %[output:5c11814a] %[output:78a37a53] %[output:106eb8c5] %[output:927adec1] %[output:7c0b8213] %[output:521d735f] %[output:3de3926b] %[output:9f944391] %[output:79aab7ea] %[output:3865bcd2] %[output:1b6c0968] %[output:5653218c] %[output:57fe2717] %[output:8413d537] %[output:9fba9d23] %[output:479094ca] %[output:84e3e778] %[output:51bf22ef] %[output:96a7280f] %[output:7e5e3c6a] %[output:74c34de5] %[output:29080772] %[output:8d521bf3] %[output:4cd25d86] %[output:82ba905e] %[output:26b33963]

writetable(BIR_result_MK,'BIR_res_MK.txt'); %, 'delimiter',',' )
writetable(BIR_result_LMSlog,'BIR_res_LMSlog.txt'); 
writetable(BIR_result_LMSlin,'BIR_res_LMSlin.txt'); 
plot_10y_in_two(BIR_result_MK,BIR_st,'y'); %[output:76a70ecd] %[output:5f0e93ed]
